package com.ryanjei.orushio.pve.map;import static org.junit.jupiter.api.Assertions.*;import com.ryanjei.orushio.pve.domain.MapProfileId;import java.nio.file.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
class YamlMapProfileRepositoryTest{@TempDir Path temp;@Test void 保存再読込削除(){YamlMapProfileRepository r=new YamlMapProfileRepository(temp);MapProfile p=MapProfileTest.complete("map-a");r.save(p);assertEquals(p.mapId(),r.find(p.mapId()).orElseThrow().mapId());r.delete(p.mapId());assertTrue(r.find(p.mapId()).isEmpty());}@Test void schema異常を拒否()throws Exception{Path f=temp.resolve("map-a/profile.yml");Files.createDirectories(f.getParent());Files.writeString(f,"schemaVersion: \"99\"\n");assertThrows(RuntimeException.class,()->new YamlMapProfileRepository(temp).find(new MapProfileId("map-a")));}}
